const raw = $input.first().json;
const body = raw.body || raw;
const label = body.label || body.url || 'Überwachte Seite';
const url = body.url || '';
const timestamp = body.timestamp || '';
const text = body.changedText || '';

// Platzhaltersatz der Dresden-Seite: solange er vorkommt, gibt es KEINE neue Veranstaltung
const placeholder = 'An dieser Stelle finden Sie zu gegebener Zeit die Ankündigung';
const hasPlaceholder = text.includes(placeholder);

let subject, mailText;
if (hasPlaceholder) {
  subject = 'Keine neuen Veranstaltungen: ' + label;
  mailText = 'Die Seite "' + label + '" wurde geändert, aber es ist weiterhin KEINE neue Veranstaltung angekündigt (Platzhaltertext vorhanden).\n\nURL: ' + url + '\nStand: ' + timestamp;
} else {
  subject = 'MÖGLICHE NEUE VERANSTALTUNG: ' + label;
  mailText = 'Auf der Seite "' + label + '" ist der Platzhaltertext verschwunden – möglicherweise wurde eine neue Veranstaltung angekündigt!\n\nBitte hier prüfen:\n' + url + '\n\nStand: ' + timestamp + '\n\n--- Überwachter Inhalt ---\n' + text.slice(0, 3000);
}

return [{ json: { subject, text: mailText } }];
